package com.hallbooking.dao;import com.hallbooking.util.DBConnection;import java.sql.*;
public class BookingDAO {public boolean book(int userId,int hallId,Date d)throws SQLException{String s="INSERT INTO bookings(user_id,hall_id,booking_date) VALUES(?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,userId);p.setInt(2,hallId);p.setDate(3,d);return p.executeUpdate()==1;}}public void cancel(int id,int userId)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE bookings SET status='CANCELLED' WHERE id=? AND user_id=?")){p.setInt(1,id);p.setInt(2,userId);p.executeUpdate();}}}
